param([string]$Directory=(Join-Path $PSScriptRoot '../artifacts/rc-live-final'))
$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot
function Hash([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
$raw=Get-Content -LiteralPath (Join-Path $Directory 'raw-result.json') -Raw | ConvertFrom-Json
$state=[ordered]@{}
foreach($entry in $raw.result.values[0].entries){$state[$entry.key]=$entry.value}
if(-not $raw.captured -or -not $raw.result.ok -or -not $state.done -or -not $state.original_restored){throw 'Live failure observation or restoration is incomplete'}
$report=[ordered]@{schema=1;version='0.4.0-rc.1';date='2026-11-11';executor='Madium';executor_build='2.0.0';roblox_build='0.747.0.7471481';platform='Windows';architecture='not independently exposed';client_pid=$raw.pid;attempted_programs=1;completed_adapter_programs=0;verified_behavioral_pairs=0;successful_adapter_latency_samples=0;status='failed_transport';outcome=$state;host_capabilities_status=200;host_capabilities_sha256=(Hash (Join-Path $Directory 'host-capabilities.json'));executable_sha256=(Hash (Join-Path $root 'target/release/luau-decompile.exe'));adapter_sha256=(Hash (Join-Path $root 'adapter/decompile.luau'));redacted_driver_sha256=(Hash (Join-Path $Directory 'driver-redacted.luau'));captured_result_sha256=(Hash (Join-Path $Directory 'raw-result.json'));generator_sha256=(Hash $PSCommandPath);configuration=[ordered]@{endpoint='http://127.0.0.1:60213/v1/decompile';timeout_seconds=0.5;cancel_on_timeout=$true;cancel_on_restore=$true;entry_output='function';bytecode_encoding='roblox_opcode227';output_policy='faithful';validation='off'};cleanup=[ordered]@{original_decompile_restored=$state.original_restored;adapter_registry_cleared=$true;owned_probe_keys_removed=$true;owned_host_service_stopped=$true};limitations=@('The native HTTP call did not finish before the adapter deadline; its underlying API has no task-cancellation handle','A successful host-side capabilities request does not identify the cause of the native transport failure','Cleanup observations confirm adapter restoration and owned globals; they do not prove native HTTP task termination','The four manually transferred function-dump programs are separate evidence, not completed adapter requests','Controlled normal-engine script extraction was not run because no Roblox Studio test-place session was connected')}
[IO.File]::WriteAllText((Join-Path $root 'docs/results/madium-live-rc.json'),($report|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false))
Write-Output 'Recorded final-binary live transport failure and successful adapter restoration; zero completed adapter requests.'
